  function App() {
    const { control, register, handleSubmit } = useForm<{
      test: {
        yourDetail: {
          firstName: string;
          lastName: string;
        };
      }[];
    }>();
    const { fields, append } = useFieldArray({
      name: 'test',
      control,
    });

    return (
      <form onSubmit={handleSubmit(noop)}>
        {fields.map((field, index) => {
          return (
            <div key={field.id}>
              <input {...register(`test.${index}.yourDetail.firstName`)} />
              <input {...register(`test.${index}.yourDetail.lastName`)} />
            </div>
          );
        })}
        <button
          type="button"
          onClick={() =>
            append({
              yourDetail: {
                firstName: 'bill',
                lastName: 'luo',
              },
            })
          }
        >
          Append
        </button>
        <input type="submit" />
      </form>
    );
  }

  render(<App />, { reactStrictMode: true });

  fireEvent.click(screen.getByRole('button', { name: 'Append' }));

  expect(
    (screen.getAllByRole('textbox')[0] as HTMLInputElement).value,
  ).toEqual('bill');
  expect(
    (screen.getAllByRole('textbox')[1] as HTMLInputElement).value,
  ).toEqual('luo');
});

it('should not populate defaultValue when field array is already mounted', async () => {
  type FormValues = {
    root: {
      test: string;
      children: { name: string }[];
    }[];
  };

  const Child = ({
    control,
    index,
    register,
  }: {
    control: Control<FormValues>;
    index: number;
    register: UseFormRegister<FormValues>;
  }) => {
    const { fields, append } = useFieldArray({
      name: `root.${index}.children`,
      control,
    });

    return (
      <div>
        {fields.map((field, k) => {
          return (
            <div key={field.id}>
              <input {...register(`root.${index}.children.${k}.name`)} />
            </div>
          );
        })}

        <button
          onClick={() => {
            append({
              name: 'test',
            });
          }}
        >
          append
        </button>
      </div>
    );
  };

  const App = () => {
    const { register, control } = useForm<FormValues>({
      defaultValues: {
        root: [
          {
            test: 'default',
            children: [
              {
                name: 'child of index 0',
              },
            ],
          },
          {
            test: 'default1',
            children: [],
          },
        ],
      },
    });
    const { fields, swap } = useFieldArray({
      control,
      name: 'root',
    });

    return (
      <div>
        {fields.map((field, index) => {
          return (
            <div key={field.id}>
              <input {...register(`root.${index}.test` as const)} />
              <Child control={control} register={register} index={index} />
            </div>
          );
        })}
        <button
          type={'button'}
          onClick={() => {
            swap(0, 1);
          }}
        >
          swap
        </button>
      </div>
    );
  };

  render(<App />);

  fireEvent.click(screen.getByRole('button', { name: 'swap' }));

  fireEvent.click(screen.getAllByRole('button', { name: 'append' })[0]);

